pieces.where:
WHERE 1=1 AND ( 
  ( 
    ( wp_usermeta.meta_key = 'wp_capabilities' AND wp_usermeta.meta_value LIKE '%\"author\"%' )
  )
) AND (user_email LIKE '%zz-users.test')

WHERE 1=1 AND ( 
  ( 
    ( wp_usermeta.meta_key = 'wp_capabilities' AND wp_usermeta.meta_value NOT LIKE '%\"author\"%' )
  )
) AND (user_email LIKE '%zz-users.test')

WHERE 1=1 AND ( 
  ( wp_usermeta.meta_key = 'wp_user_level' AND wp_usermeta.meta_value != '0' )
) AND (user_email LIKE '%zz-users.test')

WHERE 1=1 AND ( 
  ( wp_usermeta.meta_key = 'zz_score' AND CAST(wp_usermeta.meta_value AS SIGNED) > '5' )
) AND (user_email LIKE '%zz-users.test')

WHERE 1=1 AND ( 
  ( 
    ( 
      ( wp_usermeta.meta_key = 'zz_score' AND CAST(wp_usermeta.meta_value AS SIGNED) > '10' ) 
      OR 
      mt1.user_id IS NULL
    ) 
    AND 
    ( 
      ( 
        ( mt2.meta_key = 'wp_capabilities' AND mt2.meta_value LIKE '%\"author\"%' )
      )
    )
  )
) AND (user_email LIKE '%zz-users.test')

WHERE 1=1 AND (user_email LIKE '%zz-users.test') AND ( 
  ( wp_users.user_registered > '2025-02-01 23:59:59' AND wp_users.user_registered < '2025-04-01 00:00:00' )
)
